// Des: Drive one Chrome tab: navigate, settle, read the final DOM
// Flo: enable domains > Page.navigate > wait load event > poll text length until stable > optional wait + selector > flatten open shadow roots to HTML > snapshot text when closed roots exist
// I/O: Conn (caller) + URL + Opt > HTML text of the rendered page, JS error count; eval helpers for other modules
// ===================================================================
const std = @import("std"); const mem = std.mem; const cdp = @import("nt-brow-cdpz.zig");
const CF = .{ .step = 250, .calm = 2, .flat = "(function(){function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}function ser(n){if(n.nodeType===3)return esc(n.nodeValue);if(n.nodeType!==1)return '';var t=n.tagName.toLowerCase();if(t==='script'||t==='style'||t==='noscript'||t==='template')return '';var a='';for(var i=0;i<n.attributes.length;i++){var at=n.attributes[i];a+=' '+at.name+'=\"'+at.value.replace(/\"/g,'&quot;')+'\"'}var c='';if(n.shadowRoot){for(var j=0;j<n.shadowRoot.childNodes.length;j++)c+=ser(n.shadowRoot.childNodes[j])}for(var k=0;k<n.childNodes.length;k++)c+=ser(n.childNodes[k]);return '<'+t+a+'>'+c+'</'+t+'>'}return '<!DOCTYPE html>'+ser(document.documentElement)})()", .skip = @as([]const []const u8, &.{ "SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE" }) };
pub const Opt = struct { time_mill: u32 = 60000, wait: u32 = 0, sele: []const u8 = "", blok: bool = false };
pub const Rend = struct { html: []const u8, errs: u32, closed: bool };
pub const Page = struct { conn: *cdp.Conn, gpaz: std.mem.Allocator, iozz: std.Io, dead: i64 = 0,
pub fn left(self: *Page) u32 { const rem = self.dead - cdp.nowMs(self.iozz); return if (rem <= 0) 0 else @intCast(rem); }
pub fn evalVal(self: *Page, aren: std.mem.Allocator, expr: []const u8) !std.json.Value { const prm = try std.json.Stringify.valueAlloc(aren, .{ .expression = expr, .returnByValue = true, .awaitPromise = true }, .{}); const res = try self.conn.callJson(aren, "Runtime.evaluate", prm, @max(self.left(), 1)); if (res != .object) return error.CdpError; if (res.object.get("exceptionDetails") != null) return error.EvalFail; const out = res.object.get("result") orelse return error.CdpError; if (out != .object) return error.CdpError; return out.object.get("value") orelse .null; }
pub fn evalStr(self: *Page, aren: std.mem.Allocator, expr: []const u8) ![]const u8 { const val = try self.evalVal(aren, expr); return switch (val) { .string => |txt| txt, .integer => |num| try std.fmt.allocPrint(aren, "{d}", .{num}), .bool => |flg| if (flg) "true" else "false", else => "" }; }
pub fn evalNum(self: *Page, aren: std.mem.Allocator, expr: []const u8) i64 { const val = self.evalVal(aren, expr) catch return -1; return switch (val) { .integer => |num| num, .float => |flt| @intFromFloat(flt), .bool => |flg| if (flg) 1 else 0, else => 0 }; }
pub fn nap(self: *Page, mill: u32) void { std.Io.sleep(self.iozz, .fromMilliseconds(@min(mill, self.left())), .awake) catch {}; }
pub fn settle(self: *Page, aren: std.mem.Allocator) void { var prev: i64 = -2; var same: u32 = 0; while (self.left() > 0) { const cur = self.evalNum(aren, "document.body?document.body.innerText.length:0"); if (cur == prev) { same += 1; if (same >= CF.calm) return; } else same = 0; prev = cur; self.nap(CF.step); } }
pub fn navigate(self: *Page, aren: std.mem.Allocator, urlz: []const u8, opt: Opt) !void { self.dead = cdp.nowMs(self.iozz) + opt.time_mill; for ([_][]const u8{ "Page.enable", "Runtime.enable", "Log.enable" }) |mth| _ = try self.conn.callJson(aren, mth, "", @max(self.left(), 1)); if (opt.blok) { _ = try self.conn.callJson(aren, "Network.enable", "", @max(self.left(), 1)); _ = try self.conn.callJson(aren, "Network.setBlockedURLs", "{\"urls\":[\"*.png\",\"*.jpg\",\"*.jpeg\",\"*.gif\",\"*.webp\",\"*.svg\",\"*.ico\",\"*.woff\",\"*.woff2\",\"*.ttf\",\"*.mp4\",\"*.webm\",\"*.mp3\"]}", @max(self.left(), 1)); } var from: usize = self.conn.evCount(); const prm = try std.json.Stringify.valueAlloc(aren, .{ .url = urlz }, .{}); const res = try self.conn.callJson(aren, "Page.navigate", prm, @max(self.left(), 1)); if (res == .object) { if (res.object.get("errorText") != null) return error.NavFail; } _ = try self.conn.evWait(aren, "Page.loadEventFired", &from, @max(self.left(), 1)); self.settle(aren); if (opt.wait > 0) self.nap(opt.wait); if (opt.sele.len > 0) { const qry = try std.json.Stringify.valueAlloc(aren, opt.sele, .{}); const expr = try std.fmt.allocPrint(aren, "document.querySelector({s})!==null", .{qry}); while (self.left() > 0) { if (self.evalNum(aren, expr) == 1) break; self.nap(CF.step); } } }
fn nodeSkip(strs: []const std.json.Value, ntyp: []const std.json.Value, nnam: []const std.json.Value, par: []const std.json.Value, idx: usize) bool { var cur: i64 = @intCast(idx); var hops: usize = 0; while (cur >= 0 and hops < 64) : (hops += 1) { const uix: usize = @intCast(cur); if (ntyp[uix] == .integer and ntyp[uix].integer == 1 and nnam[uix] == .integer) { const nix = nnam[uix].integer; if (nix >= 0 and @as(usize, @intCast(nix)) < strs.len and strs[@intCast(nix)] == .string) { for (CF.skip) |sk| if (std.ascii.eqlIgnoreCase(sk, strs[@intCast(nix)].string)) return true; } } cur = if (par[uix] == .integer) par[uix].integer else -1; } return false; }
pub fn snapText(self: *Page, aren: std.mem.Allocator) !struct { text: []const u8, closed: bool } { const res = try self.conn.callJson(aren, "DOMSnapshot.captureSnapshot", "{\"computedStyles\":[]}", @max(self.left(), 1)); if (res != .object) return error.CdpError; const strv = res.object.get("strings") orelse return error.CdpError; const docs = res.object.get("documents") orelse return error.CdpError; if (strv != .array or docs != .array) return error.CdpError; var outp: std.ArrayList(u8) = .empty; var closed = false; for (docs.array.items) |doc| { if (doc != .object) continue; const nodes = doc.object.get("nodes") orelse continue; if (nodes != .object) continue; if (nodes.object.get("shadowRootType")) |srt| { if (srt == .object) { if (srt.object.get("value")) |vals| { if (vals == .array) { for (vals.array.items) |vi| { if (vi == .integer and vi.integer >= 0 and @as(usize, @intCast(vi.integer)) < strv.array.items.len) { const sv = strv.array.items[@intCast(vi.integer)]; if (sv == .string and mem.eql(u8, sv.string, "closed")) closed = true; } } } } } } const ntyp = (nodes.object.get("nodeType") orelse continue); const nval = (nodes.object.get("nodeValue") orelse continue); const nnam = (nodes.object.get("nodeName") orelse continue); const par = (nodes.object.get("parentIndex") orelse continue); if (ntyp != .array or nval != .array or nnam != .array or par != .array) continue; const cnt = @min(@min(ntyp.array.items.len, nval.array.items.len), @min(nnam.array.items.len, par.array.items.len)); for (0..cnt) |ix| { if (ntyp.array.items[ix] != .integer or ntyp.array.items[ix].integer != 3) continue; if (nval.array.items[ix] != .integer) continue; const si = nval.array.items[ix].integer; if (si < 0 or @as(usize, @intCast(si)) >= strv.array.items.len) continue; const sv = strv.array.items[@intCast(si)]; if (sv != .string) continue; if (nodeSkip(strv.array.items, ntyp.array.items[0..cnt], nnam.array.items[0..cnt], par.array.items[0..cnt], ix)) continue; const trm = mem.trim(u8, sv.string, " \t\r\n"); if (trm.len == 0) continue; try outp.appendSlice(aren, trm); try outp.append(aren, '\n'); } } return .{ .text = outp.items, .closed = closed }; }
fn escHtml(aren: std.mem.Allocator, txt: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; for (txt) |chr| switch (chr) { '&' => try outp.appendSlice(aren, "&amp;"), '<' => try outp.appendSlice(aren, "&lt;"), '>' => try outp.appendSlice(aren, "&gt;"), else => try outp.append(aren, chr) }; return outp.toOwnedSlice(aren); }
pub fn errCount(self: *Page) u32 { return self.conn.evHas("Runtime.exceptionThrown") + self.conn.evHas("\"level\":\"error\""); }
pub fn grab(self: *Page, aren: std.mem.Allocator) !Rend { const flat = try self.evalStr(aren, CF.flat); const snp = self.snapText(aren) catch return .{ .html = flat, .errs = self.errCount(), .closed = false }; if (!snp.closed) return .{ .html = flat, .errs = self.errCount(), .closed = false }; const titl = self.evalStr(aren, "document.title") catch ""; var outp: std.ArrayList(u8) = .empty; try outp.print(aren, "<!DOCTYPE html><html><head><title>{s}</title></head><body>", .{try escHtml(aren, titl)}); var itr = mem.splitScalar(u8, snp.text, '\n'); while (itr.next()) |ln| { if (ln.len == 0) continue; try outp.print(aren, "<p>{s}</p>", .{try escHtml(aren, ln)}); } try outp.appendSlice(aren, "</body></html>"); return .{ .html = outp.items, .errs = self.errCount(), .closed = true }; }
};
pub fn pageOpen(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, wspath: []const u8, mill: u32) !Page { const conn = try cdp.connect(gpaz, iozz, port, wspath, mill); return .{ .conn = conn, .gpaz = gpaz, .iozz = iozz }; }
